insert into exercises (name, category, muscle_group, secondary_muscles, equipment, mechanics, instructions, is_public) values
('Panca piana bilanciere', 'multiarticolare', 'petto', array['tricipiti','spalle'], 'bilanciere', 'spinta orizzontale', 'Scapole addotte e piedi ben piantati a terra. Scendi con il bilanciere al petto e spingi senza perdere l''arco lombare.', true),
('Panca inclinata bilanciere', 'multiarticolare', 'petto', array['spalle','tricipiti'], 'bilanciere', 'spinta orizzontale', 'Panca inclinata a 30-45 gradi. Porta il bilanciere alla parte alta del petto e spingi verso l''alto.', true),
('Panca declinata bilanciere', 'multiarticolare', 'petto', array['tricipiti'], 'bilanciere', 'spinta orizzontale', 'Blocca le gambe sulla panca declinata. Scendi con controllo verso la parte bassa del petto e spingi.', true),
('Panca piana manubri', 'multiarticolare', 'petto', array['tricipiti','spalle'], 'manubri', 'spinta orizzontale', 'Impugna i manubri sopra il petto e scendi ampliando leggermente la traiettoria. Spingi riavvicinando i manubri in alto.', true),
('Panca inclinata manubri', 'multiarticolare', 'petto', array['spalle','tricipiti'], 'manubri', 'spinta orizzontale', 'Su panca inclinata scendi con i gomiti a circa 45 gradi dal busto. Spingi i manubri verso l''alto senza farli sbattere.', true),
('Croci su panca piana manubri', 'isolamento', 'petto', null, 'manubri', 'isolamento', 'Braccia semitese, apri i manubri in un ampio arco fino a sentire allungare il petto. Richiudi come per abbracciare un albero.', true),
('Croci su panca inclinata manubri', 'isolamento', 'petto', null, 'manubri', 'isolamento', 'Su panca inclinata apri le braccia mantenendo i gomiti leggermente flessi. Controlla la fase di discesa.', true),
('Croci ai cavi alti', 'isolamento', 'petto', null, 'cavo', 'isolamento', 'Dai cavi alti porta le mani in basso e in avanti fino a incrociarle. Mantieni il busto leggermente inclinato.', true),
('Croci ai cavi bassi', 'isolamento', 'petto', array['spalle'], 'cavo', 'isolamento', 'Dai cavi bassi solleva le braccia in avanti e verso l''alto. Strizza il petto alto a fine corsa.', true),
('Chest press', 'multiarticolare', 'petto', array['tricipiti','spalle'], 'macchina', 'spinta orizzontale', 'Regola il sedile con le maniglie all''altezza del petto. Spingi in avanti senza bloccare i gomiti.', true),
('Chest press inclinata', 'multiarticolare', 'petto', array['spalle','tricipiti'], 'macchina', 'spinta verticale', 'Spingi le maniglie in alto e in avanti mantenendo la schiena appoggiata. Torna con controllo.', true),
('Pectoral machine', 'isolamento', 'petto', null, 'macchina', 'isolamento', 'Gomiti alla stessa altezza delle spalle. Chiudi le braccia davanti al petto e trattieni un secondo la contrazione.', true),
('Dip alle parallele', 'multiarticolare', 'petto', array['tricipiti','spalle'], 'corpo libero', 'spinta verticale', 'Busto leggermente inclinato in avanti per enfatizzare il petto. Scendi finché le spalle non arrivano sotto i gomiti.', true),
('Piegamenti sulle braccia', 'multiarticolare', 'petto', array['tricipiti','core'], 'corpo libero', 'spinta orizzontale', 'Corpo in linea dalla testa ai talloni. Scendi con il petto verso terra e spingi contraendo l''addome.', true),
('Piegamenti con piedi rialzati', 'multiarticolare', 'petto', array['spalle','tricipiti'], 'corpo libero', 'spinta orizzontale', 'Appoggia i piedi su un rialzo per enfatizzare il petto alto. Mantieni il bacino in linea con le spalle.', true),
('Pullover con manubrio', 'isolamento', 'petto', array['dorso','tricipiti'], 'manubri', 'isolamento', 'Sdraiato di traverso sulla panca, porta il manubrio dietro la testa con braccia semitese. Riporta sopra il petto espirando.', true),
('Chest press con elastici', 'multiarticolare', 'petto', array['tricipiti'], 'elastici', 'spinta orizzontale', 'Elastico dietro la schiena, spingi le mani in avanti fino a distendere le braccia. Controlla il ritorno.', true),
('Trazioni alla sbarra presa prona', 'multiarticolare', 'dorso', array['bicipiti','core'], 'corpo libero', 'trazione verticale', 'Presa poco piu larga delle spalle. Tira il petto verso la sbarra portando i gomiti verso il basso.', true),
('Trazioni presa supina', 'multiarticolare', 'dorso', array['bicipiti'], 'corpo libero', 'trazione verticale', 'Palmi rivolti verso di te, larghezza spalle. Sali fino a superare la sbarra con il mento e scendi con controllo.', true),
('Trazioni presa neutra', 'multiarticolare', 'dorso', array['bicipiti'], 'corpo libero', 'trazione verticale', 'Impugna le maniglie parallele e tira i gomiti verso i fianchi. Evita di dondolare con il corpo.', true),
('Lat machine presa larga', 'multiarticolare', 'dorso', array['bicipiti'], 'macchina', 'trazione verticale', 'Porta la barra verso la parte alta del petto aprendo il torace. Non tirare dietro la nuca.', true),
('Lat machine presa inversa', 'multiarticolare', 'dorso', array['bicipiti'], 'macchina', 'trazione verticale', 'Presa supina larghezza spalle. Tira la barra al petto tenendo i gomiti vicini al busto.', true),
('Lat machine presa neutra', 'multiarticolare', 'dorso', array['bicipiti'], 'macchina', 'trazione verticale', 'Con il triangolo o le maniglie parallele tira verso lo sterno. Petto in fuori e spalle basse.', true),
('Rematore seduto cavo', 'multiarticolare', 'dorso', array['bicipiti','spalle'], 'cavo', 'trazione orizzontale', 'Busto eretto e ginocchia morbide. Tira la maniglia all''addome portando le scapole indietro.', true),
('Rematore con bilanciere', 'multiarticolare', 'dorso', array['bicipiti','femorali'], 'bilanciere', 'trazione orizzontale', 'Busto inclinato a circa 45 gradi con schiena neutra. Tira il bilanciere verso l''ombelico e controlla la discesa.', true);
insert into exercises (name, category, muscle_group, secondary_muscles, equipment, mechanics, instructions, is_public) values
('Rematore con manubrio a un braccio', 'multiarticolare', 'dorso', array['bicipiti'], 'manubri', 'trazione orizzontale', 'Mano e ginocchio in appoggio sulla panca. Tira il manubrio verso il fianco senza ruotare il busto.', true),
('Rematore T-bar', 'multiarticolare', 'dorso', array['bicipiti'], 'bilanciere', 'trazione orizzontale', 'Bilanciere ancorato a terra, busto inclinato. Tira il carico verso il petto mantenendo la schiena neutra.', true),
('Rematore alla macchina', 'multiarticolare', 'dorso', array['bicipiti'], 'macchina', 'trazione orizzontale', 'Petto appoggiato al supporto. Tira le maniglie indietro concentrandoti sulla chiusura delle scapole.', true),
('Rematore inverso alla sbarra', 'multiarticolare', 'dorso', array['bicipiti','core'], 'corpo libero', 'trazione orizzontale', 'Corpo in linea sotto la sbarra bassa. Tira il petto verso la sbarra e scendi lentamente.', true),
('Rematore con elastici', 'multiarticolare', 'dorso', array['bicipiti'], 'elastici', 'trazione orizzontale', 'Elastico ancorato davanti a te. Tira le mani verso i fianchi stringendo le scapole.', true),
('Pulldown a braccia tese ai cavi', 'isolamento', 'dorso', array['tricipiti'], 'cavo', 'trazione verticale', 'Braccia quasi tese, porta la barra dal cavo alto verso le cosce. Senti lavorare il gran dorsale.', true),
('Hyperextension alla panca', 'isolamento', 'dorso', array['glutei','femorali'], 'panca', 'hinge', 'Bacino appoggiato al cuscino, scendi con il busto e risali fino alla linea del corpo. Non iperestendere la schiena.', true),
('Shrug con bilanciere', 'isolamento', 'dorso', null, 'bilanciere', 'isolamento', 'Braccia distese, solleva le spalle verso le orecchie e trattieni un secondo. Evita di ruotare le spalle.', true),
('Shrug con manubri', 'isolamento', 'dorso', null, 'manubri', 'isolamento', 'Manubri lungo i fianchi, alza le spalle in verticale con controllo. Non piegare i gomiti.', true),
('Lento avanti bilanciere', 'multiarticolare', 'spalle', array['tricipiti','core'], 'bilanciere', 'spinta verticale', 'In piedi con addome contratto, spingi il bilanciere sopra la testa fino a braccia distese. Non inarcare la zona lombare.', true),
('Lento avanti manubri seduto', 'multiarticolare', 'spalle', array['tricipiti'], 'manubri', 'spinta verticale', 'Seduto con schienale alto, spingi i manubri verso l''alto avvicinandoli a fine corsa. Scendi fino alle orecchie.', true),
('Arnold press', 'multiarticolare', 'spalle', array['tricipiti'], 'manubri', 'spinta verticale', 'Parti con i palmi verso di te e ruota i manubri durante la spinta. Movimento fluido e controllato.', true),
('Shoulder press macchina', 'multiarticolare', 'spalle', array['tricipiti'], 'macchina', 'spinta verticale', 'Schiena appoggiata e maniglie all''altezza delle spalle. Spingi in alto senza bloccare i gomiti.', true),
('Push press bilanciere', 'multiarticolare', 'spalle', array['tricipiti','quadricipiti'], 'bilanciere', 'spinta verticale', 'Piccolo piegamento di gambe e spinta esplosiva del bilanciere sopra la testa. Blocca il carico con il core attivo.', true),
('Alzate laterali manubri', 'isolamento', 'spalle', null, 'manubri', 'isolamento', 'Solleva i manubri lateralmente fino all''altezza delle spalle con i gomiti leggermente flessi. Scendi lentamente.', true),
('Alzate laterali al cavo', 'isolamento', 'spalle', null, 'cavo', 'isolamento', 'Cavo basso dietro il corpo, alza il braccio lateralmente mantenendo tensione costante. Non superare la linea della spalla.', true),
('Alzate laterali con elastici', 'isolamento', 'spalle', null, 'elastici', 'isolamento', 'Elastico sotto i piedi, solleva le braccia lateralmente fino alle spalle. Controlla il ritorno.', true),
('Alzate frontali manubri', 'isolamento', 'spalle', null, 'manubri', 'isolamento', 'Solleva i manubri davanti a te fino all''altezza degli occhi. Evita slanci con il busto.', true),
('Alzate posteriori manubri busto flesso', 'isolamento', 'spalle', array['dorso'], 'manubri', 'isolamento', 'Busto flesso in avanti, apri le braccia lateralmente puntando i gomiti verso il soffitto. Non usare slancio.', true),
('Croci inverse alla macchina', 'isolamento', 'spalle', array['dorso'], 'macchina', 'isolamento', 'Petto contro lo schienale, apri le braccia indietro fino alla linea delle spalle. Trattieni la contrazione.', true),
('Face pull ai cavi', 'isolamento', 'spalle', array['dorso'], 'cavo', 'trazione orizzontale', 'Tira la corda verso il viso separando le mani a fine corsa. Gomiti alti e spalle basse.', true),
('Tirate al mento bilanciere', 'multiarticolare', 'spalle', array['bicipiti','dorso'], 'bilanciere', 'trazione verticale', 'Presa poco piu stretta delle spalle, tira il bilanciere verso il petto guidando con i gomiti. Non superare la linea delle spalle.', true),
('Lento avanti con kettlebell', 'multiarticolare', 'spalle', array['tricipiti','core'], 'kettlebell', 'spinta verticale', 'Kettlebell in appoggio sull''avambraccio, spingi sopra la testa mantenendo il polso neutro. Core sempre attivo.', true),
('Alzate a Y su panca inclinata', 'isolamento', 'spalle', array['dorso'], 'manubri', 'isolamento', 'Petto appoggiato alla panca inclinata, solleva i manubri in diagonale formando una Y. Pollici verso l''alto.', true),
('Curl bilanciere in piedi', 'isolamento', 'bicipiti', array['core'], 'bilanciere', 'isolamento', 'Gomiti fermi ai fianchi, fletti le braccia portando il bilanciere alle spalle. Scendi in modo controllato senza dondolare.', true);
insert into exercises (name, category, muscle_group, secondary_muscles, equipment, mechanics, instructions, is_public) values
('Curl con bilanciere EZ', 'isolamento', 'bicipiti', null, 'bilanciere', 'isolamento', 'Impugna la barra EZ sulle curve interne. Fletti i gomiti tenendoli fermi lungo i fianchi.', true),
('Curl manubri alternato', 'isolamento', 'bicipiti', null, 'manubri', 'isolamento', 'Fletti un braccio alla volta supinando il polso durante la salita. Non oscillare con il busto.', true),
('Curl a martello manubri', 'isolamento', 'bicipiti', array['tricipiti'], 'manubri', 'isolamento', 'Presa neutra con i palmi rivolti verso il corpo. Fletti i gomiti mantenendo i polsi bloccati.', true),
('Curl concentrato manubrio', 'isolamento', 'bicipiti', null, 'manubri', 'isolamento', 'Seduto, gomito appoggiato all''interno coscia. Fletti lentamente concentrandoti sul picco di contrazione.', true),
('Curl su panca inclinata', 'isolamento', 'bicipiti', null, 'manubri', 'isolamento', 'Schiena appoggiata alla panca inclinata e braccia perpendicolari a terra. Fletti mantenendo le spalle indietro.', true),
('Curl ai cavi', 'isolamento', 'bicipiti', null, 'cavo', 'isolamento', 'Dal cavo basso fletti i gomiti con tensione costante. Non far riposare il carico a fine discesa.', true),
('Curl a martello ai cavi con corda', 'isolamento', 'bicipiti', null, 'cavo', 'isolamento', 'Impugna la corda con presa neutra e fletti i gomiti. Mantieni i gomiti fermi ai fianchi.', true),
('Curl alla panca Scott', 'isolamento', 'bicipiti', null, 'panca', 'isolamento', 'Braccia appoggiate al cuscino inclinato. Fletti fino in alto e scendi senza distendere completamente i gomiti.', true),
('Curl alla macchina', 'isolamento', 'bicipiti', null, 'macchina', 'isolamento', 'Regola il sedile con le ascelle appoggiate al cuscino. Fletti e trattieni un secondo in contrazione.', true),
('Curl con elastici', 'isolamento', 'bicipiti', null, 'elastici', 'isolamento', 'Elastico sotto i piedi, fletti i gomiti mantenendoli fermi. Controlla la fase di ritorno.', true),
('French press con bilanciere EZ', 'isolamento', 'tricipiti', null, 'bilanciere', 'isolamento', 'Sdraiato sulla panca, fletti i gomiti portando la barra verso la fronte. Gomiti fermi e paralleli.', true),
('Pushdown ai cavi con corda', 'isolamento', 'tricipiti', null, 'cavo', 'isolamento', 'Gomiti bloccati ai fianchi, distendi le braccia separando la corda in basso. Torna su con controllo.', true),
('Pushdown ai cavi con barra', 'isolamento', 'tricipiti', null, 'cavo', 'isolamento', 'Spingi la barra verso il basso fino a distendere i gomiti. Spalle basse e busto stabile.', true),
('French press con manubrio seduto', 'isolamento', 'tricipiti', null, 'manubri', 'isolamento', 'Manubrio a due mani dietro la testa. Distendi le braccia verso l''alto tenendo i gomiti stretti.', true),
('Estensioni sopra la testa al cavo', 'isolamento', 'tricipiti', null, 'cavo', 'isolamento', 'Di spalle al cavo basso, distendi le braccia sopra la testa. Mantieni i gomiti vicini alle orecchie.', true),
('Estensioni con elastici sopra la testa', 'isolamento', 'tricipiti', null, 'elastici', 'isolamento', 'Elastico ancorato in basso dietro di te. Distendi le braccia sopra la testa senza aprire i gomiti.', true),
('Panca piana presa stretta', 'multiarticolare', 'tricipiti', array['petto','spalle'], 'bilanciere', 'spinta orizzontale', 'Presa alla larghezza delle spalle, gomiti vicini al busto. Scendi al petto basso e spingi in alto.', true),
('Dip tra panche', 'multiarticolare', 'tricipiti', array['petto','spalle'], 'panca', 'spinta verticale', 'Mani sul bordo della panca e gambe distese in avanti. Scendi flettendo i gomiti e risali spingendo.', true),
('Kickback con manubrio', 'isolamento', 'tricipiti', null, 'manubri', 'isolamento', 'Busto flesso e braccio parallelo al pavimento. Distendi il gomito indietro e trattieni la contrazione.', true),
('Piegamenti diamante', 'multiarticolare', 'tricipiti', array['petto','core'], 'corpo libero', 'spinta orizzontale', 'Mani unite sotto il petto a formare un rombo. Scendi con i gomiti stretti e spingi.', true),
('Estensioni tricipiti alla macchina', 'isolamento', 'tricipiti', null, 'macchina', 'isolamento', 'Gomiti appoggiati al cuscino, distendi le braccia verso il basso. Non sollevare le spalle.', true),
('Squat con bilanciere', 'multiarticolare', 'quadricipiti', array['glutei','femorali','core'], 'bilanciere', 'squat', 'Bilanciere sui trapezi e piedi larghezza spalle. Scendi sotto il parallelo mantenendo la schiena neutra e spingi con tutto il piede.', true),
('Front squat bilanciere', 'multiarticolare', 'quadricipiti', array['glutei','core'], 'bilanciere', 'squat', 'Bilanciere in appoggio sulle spalle anteriori con gomiti alti. Scendi tenendo il busto il piu verticale possibile.', true),
('Goblet squat con kettlebell', 'multiarticolare', 'quadricipiti', array['glutei','core'], 'kettlebell', 'squat', 'Kettlebell al petto, scendi tra le ginocchia mantenendo i talloni a terra. Risali spingendo il pavimento.', true),
('Leg press', 'multiarticolare', 'quadricipiti', array['glutei','femorali'], 'macchina', 'squat', 'Piedi al centro della pedana, scendi finché le ginocchia raggiungono circa 90 gradi. Non staccare il bacino dal sedile.', true);
insert into exercises (name, category, muscle_group, secondary_muscles, equipment, mechanics, instructions, is_public) values
('Leg extension', 'isolamento', 'quadricipiti', null, 'macchina', 'isolamento', 'Regola il rullo sopra le caviglie. Distendi le gambe e trattieni un secondo in massima contrazione.', true),
