('Squat bulgaro con manubri', 'multiarticolare', 'quadricipiti', array['glutei','femorali'], 'manubri', 'lunge', 'Piede posteriore in appoggio sulla panca. Scendi in verticale con il busto leggermente inclinato in avanti.', true),
('Step-up su panca con manubri', 'multiarticolare', 'quadricipiti', array['glutei'], 'manubri', 'lunge', 'Sali sulla panca spingendo con la gamba in appoggio, senza darti slancio con quella a terra. Scendi con controllo.', true),
('Squat a corpo libero', 'multiarticolare', 'quadricipiti', array['glutei','core'], 'corpo libero', 'squat', 'Piedi larghezza spalle e braccia avanti per bilanciare. Scendi sotto il parallelo mantenendo i talloni a terra.', true),
('Pistol squat', 'multiarticolare', 'quadricipiti', array['glutei','core'], 'corpo libero', 'squat', 'Squat su una gamba con l''altra distesa in avanti. Scendi lentamente mantenendo l''equilibrio.', true),
('Sissy squat', 'isolamento', 'quadricipiti', null, 'corpo libero', 'squat', 'In piedi sugli avampiedi, piega le ginocchia in avanti inclinando il busto indietro in linea con le cosce. Movimento lento.', true),
('Sedia al muro', 'isolamento', 'quadricipiti', array['glutei'], 'corpo libero', 'squat', 'Schiena contro il muro e cosce parallele al pavimento. Mantieni la posizione respirando in modo regolare.', true),
('Leg curl sdraiato', 'isolamento', 'femorali', null, 'macchina', 'isolamento', 'Rullo sopra i talloni, fletti le ginocchia portando i talloni ai glutei. Non sollevare il bacino dal cuscino.', true),
('Leg curl seduto', 'isolamento', 'femorali', null, 'macchina', 'isolamento', 'Regola i cuscini su cosce e caviglie. Fletti le ginocchia verso il basso e torna con controllo.', true),
('Leg curl in piedi al cavo', 'isolamento', 'femorali', null, 'cavo', 'isolamento', 'Cavigliera collegata al cavo basso. Fletti il ginocchio portando il tallone al gluteo senza muovere il bacino.', true),
('Leg curl con elastico', 'isolamento', 'femorali', null, 'elastici', 'isolamento', 'Elastico ancorato in basso e fissato alla caviglia. Fletti il ginocchio con movimento lento e controllato.', true),
('Stacco rumeno con bilanciere', 'multiarticolare', 'femorali', array['glutei','dorso'], 'bilanciere', 'hinge', 'Ginocchia poco flesse, spingi il bacino indietro facendo scorrere il bilanciere lungo le gambe. Risali contraendo i glutei.', true),
('Romanian deadlift manubri', 'multiarticolare', 'femorali', array['glutei','dorso'], 'manubri', 'hinge', 'Manubri davanti alle cosce, fletti il bacino indietro con schiena neutra. Senti l''allungamento dei femorali e risali.', true),
('Stacco a gambe tese bilanciere', 'multiarticolare', 'femorali', array['glutei','dorso'], 'bilanciere', 'hinge', 'Gambe quasi distese, scendi con il busto mantenendo la schiena in posizione neutra. Non arrotondare la zona lombare.', true),
('Good morning con bilanciere', 'multiarticolare', 'femorali', array['glutei','dorso'], 'bilanciere', 'hinge', 'Bilanciere sui trapezi, fletti il busto in avanti spingendo il bacino indietro. Risali contraendo glutei e femorali.', true),
('Nordic curl', 'isolamento', 'femorali', array['glutei'], 'corpo libero', 'isolamento', 'Caviglie bloccate, scendi in avanti frenando con i femorali il piu a lungo possibile. Aiutati con le mani a risalire.', true),
('Sliding leg curl', 'isolamento', 'femorali', array['glutei','core'], 'corpo libero', 'isolamento', 'Supino con talloni su dischi scivolosi, solleva il bacino e fletti le ginocchia facendo scorrere i piedi verso i glutei.', true),
('Hip thrust con bilanciere', 'multiarticolare', 'glutei', array['femorali','core'], 'bilanciere', 'hinge', 'Schiena alta appoggiata alla panca e bilanciere sul bacino. Spingi il bacino in alto fino alla linea del corpo e strizza i glutei.', true),
('Ponte glutei a corpo libero', 'isolamento', 'glutei', array['femorali'], 'corpo libero', 'hinge', 'Supino con ginocchia flesse, solleva il bacino contraendo i glutei. Trattieni un secondo in alto.', true),
('Hip thrust a una gamba', 'isolamento', 'glutei', array['femorali','core'], 'corpo libero', 'hinge', 'Spalle sulla panca e una gamba sollevata. Spingi il bacino in alto con la gamba in appoggio.', true),
('Swing con kettlebell', 'multiarticolare', 'glutei', array['femorali','core','dorso'], 'kettlebell', 'hinge', 'Movimento esplosivo di anca: spingi il bacino indietro e poi in avanti facendo salire il kettlebell al petto. Braccia rilassate.', true);
insert into exercises (name, category, muscle_group, secondary_muscles, equipment, mechanics, instructions, is_public) values
('Slanci posteriori al cavo', 'isolamento', 'glutei', array['femorali'], 'cavo', 'isolamento', 'Cavigliera al cavo basso, spingi la gamba indietro contraendo il gluteo. Busto fermo e core attivo.', true),
('Slanci posteriori a quattro appoggi', 'isolamento', 'glutei', array['femorali'], 'corpo libero', 'isolamento', 'In quadrupedia, spingi il tallone verso il soffitto con ginocchio flesso. Non inarcare la zona lombare.', true),
('Abduzioni alla macchina', 'isolamento', 'glutei', null, 'macchina', 'isolamento', 'Seduto con schiena appoggiata, apri le ginocchia contro la resistenza. Torna lentamente senza far cadere il carico.', true),
